}

impl Validator {
    pub fn new(config: ValidatorConfig) -> Self {
        Self { config }
    }

    pub fn validate(
        &self,
        action: &Action,
        observation: &Observation,
    ) -> Result<(), Vec<ValidationError>> {
        let element_ids: HashSet<&str> =
            observation.elements.iter().map(|el| el.id.as_str()).collect();
        let mut errors = Vec::new();

        match action {
            Action::Click { id } => {
                validate_element_id(id, &element_ids, &mut errors);
            }
            Action::Type { id, text, .. } => {
                validate_element_id(id, &element_ids, &mut errors);
                let length = text.chars().count();
                if length > self.config.max_text_len {
                    errors.push(ValidationError::new(
                        "text_too_long",
                        Some("text"),
                        format!(
                            "text length {} exceeds max {}",
                            length,
                            self.config.max_text_len
                        ),
                    ));
                }
            }
            Action::Select { id, .. } => {
                validate_element_id(id, &element_ids, &mut errors);
            }
            Action::Scroll { dx, dy } => {
                let limit = self.config.max_scroll;
                if exceeds_symmetric_limit_i64(*dx, limit) || exceeds_symmetric_limit_i64(*dy, limit)
                {
                    errors.push(ValidationError::new(
                        "scroll_out_of_bounds",
                        Some("scroll"),
                        format!(
                            "scroll out of bounds: dx={dx}, dy={dy}, max={limit}"
                        ),
                    ));
                }
            }
            Action::Wait { ms } => {
                if wait_exceeds_max(*ms, self.config.max_wait_ms) {
                    errors.push(ValidationError::new(
                        "wait_too_long",
                        Some("ms"),
                        format!(
                            "wait {ms}ms exceeds max {}ms",
                            self.config.max_wait_ms
                        ),
                    ));
                }
            }
            Action::Navigate { url } => {
                match parse_navigate_url(url) {
                    Ok(parsed) => {
                        if let Some(error) =
                            evaluate_url_policy(&parsed, self.config.allow_insecure)
                        {
                            errors.push(error);
                        }
                    }
                    Err(error) => errors.push(error),
                }
            }
            Action::Back => {}
            Action::Extract { id, .. } => {
                if let Some(id) = id.as_ref() {
                    validate_element_id(id, &element_ids, &mut errors);
                }
            }
            Action::Done { .. } => {}
        }

        if errors.is_empty() {
            Ok(())
        } else {
            Err(errors)
        }
    }
}

fn validate_element_id(id: &str, element_ids: &HashSet<&str>, errors: &mut Vec<ValidationError>) {
    if id.trim().is_empty() {
        errors.push(ValidationError::new(
            "missing_id",
            Some("id"),
            "action id is required",
        ));
        return;
    }

    if !element_ids.contains(id) {
        errors.push(ValidationError::new(
            "unknown_id",
            Some("id"),
            format!("id {id} not found in observation"),
        ));
    }
}

fn wait_exceeds_max(ms: u64, max_wait_ms: u64) -> bool {
    Duration::from_millis(ms) > Duration::from_millis(max_wait_ms)
}

fn parse_navigate_url(raw: &str) -> Result<Url, ValidationError> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(ValidationError::new(
            "missing_url",
            Some("url"),
            "navigate url is required",
        ));
    }
    Url::parse(trimmed).map_err(|err| {
        ValidationError::new(
            "invalid_url",
            Some("url"),
            format!("invalid url {trimmed}: {err}"),
        )
    })
}

fn evaluate_url_policy(url: &Url, allow_insecure: bool) -> Option<ValidationError> {
    if allow_insecure {
        return None;
    }

    match url.scheme() {
        "http" | "https" => None,
        other => Some(ValidationError::new(
            "insecure_url",
            Some("url"),
            format!("unsupported url scheme '{other}'"),
        )),
    }
}
